        assert_eq!(app.registers[&'a'].text, "ab");
        assert_eq!(app.registers[&'"'].text, "ab");

        app.panes.get_mut(&0).unwrap().selection = Selection::single(Range::new(2, 3));
        press(&mut app, '"');
